using System.Net;
using System.Text;
using System.Text.Json;
namespace Nuzul;

public static class Reports
{
    static string E(string? s) => WebUtility.HtmlEncode(s ?? "");
    public static object Document(Project p) { var results = p.Runs.SelectMany(run => run.Results.Select(r => new { runId = run.Id, record = r })).ToList(); var defects = results.Where(x => x.record.Outcome == "Failed" && x.record.AssertionOutcome != "Human observation; not an automated deterministic assertion").Select((x, i) => { var snapshot = p.Runs.First(r => r.Id == x.runId); var t = snapshot.TestCasesSnapshot.FirstOrDefault(t => t.Id == x.record.TestCaseId) ?? p.TestCases.FirstOrDefault(t => t.Id == x.record.TestCaseId); return new { bugId = $"SARJ-BUG-{i + 1:000}", title = p.Defects.FirstOrDefault(d => d.EvidenceReference == x.record.EvidenceReference)?.Title ?? t?.Title, description = p.Defects.FirstOrDefault(d => d.EvidenceReference == x.record.EvidenceReference)?.Description ?? "Deterministic assertion failed against the configured target.", reproductionSteps = p.Defects.FirstOrDefault(d => d.EvidenceReference == x.record.EvidenceReference)?.ReproductionSteps ?? t?.Steps, expectedResult = x.record.ExpectedResult, actualResult = x.record.ActualResult, assertion = x.record.AssertionOutcome, evidence = x.record.EvidenceReference, severity = p.Defects.FirstOrDefault(d => d.EvidenceReference == x.record.EvidenceReference)?.Severity ?? "Needs triage", priority = p.Defects.FirstOrDefault(d => d.EvidenceReference == x.record.EvidenceReference)?.Priority ?? t?.Priority, status = p.Defects.FirstOrDefault(d => d.EvidenceReference == x.record.EvidenceReference)?.Status ?? "Open", requirementId = t?.RequirementId, runId = x.runId }; }); return new { title = "Sarj QA Studio — Evidence Report", generatedAt = DateTimeOffset.UtcNow, target = p.Settings.BaseUrl, fixtureNotice = "Results apply only to the configured target. Local demonstration fixtures are not the Nuzul Staff Console.", project = p, defectTriage = p.Defects, summary = results.GroupBy(x => x.record.Outcome).ToDictionary(g => g.Key, g => g.Count()), defects, limitations = new[] { "Static screenshots are manual evidence; no undocumented endpoints inferred.", "AI suggestions are not test outcomes. Automated assertions are deterministic.", "Defect severity and root cause require human triage.", "Preflight and network/authentication failures are Blocked, not product defects." }, traceability = p.TestCases.Select(t => new { testCaseId = t.Id, requirementId = t.RequirementId, source = p.Requirements.FirstOrDefault(r => r.Id == t.RequirementId) }) }; }
    public static string Html(Project p, string language = "en")
    {
        var ar = language == "ar";
        string L(string en, string arabic) => ar ? arabic : en;
        string Outcome(string value) => value switch {
            "Passed" => L("Passed", "ناجح"), "Failed" => L("Failed", "فاشل"),
            "Blocked" => L("Blocked", "متعذر"), "Running" => L("Running", "قيد التنفيذ"), _ => value };
        var b = new StringBuilder($"<!doctype html><html lang='{(ar ? "ar" : "en")}' dir='{(ar ? "rtl" : "ltr")}'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Sarj QA — {L("Evidence report", "تقرير الأدلة")}</title>");
        // Self-contained approved Arabic font: downloaded reports also work offline.
        if (ar) {
            var font = Path.Combine(Environment.GetEnvironmentVariable("ASPNETCORE_WEBROOT") ?? Path.Combine(AppContext.BaseDirectory, "wwwroot"), "fonts", "Brando-Regular.woff2");
            if (File.Exists(font)) b.Append("<style>@font-face{font-family:SarjArabic;src:url(data:font/woff2;base64,").Append(Convert.ToBase64String(File.ReadAllBytes(font))).Append(") format('woff2');font-weight:400;font-display:swap}</style>");
        }
        b.Append("<style>body{font:16px SarjArabic,Inter,sans-serif;max-width:1100px;margin:32px auto;padding:20px;background:#0b111a;color:#e6edf5;line-height:1.8}table{border-collapse:collapse;width:100%;margin-block:24px}td,th{padding:12px;border:1px solid #39495e;text-align:start;overflow-wrap:anywhere}th{background:#172536}pre{direction:ltr;text-align:left;white-space:pre-wrap;overflow-wrap:anywhere;background:#142131;padding:16px;border-radius:8px}h1,h2{color:#6be5cc}.Failed{color:#ffb5bc}.Passed{color:#76e5ba}details{margin-block:16px}summary{cursor:pointer;font-weight:bold}a{color:#81caff}@media(max-width:600px){body{padding:12px;margin:0}td,th{padding:6px;font-size:14px}}@media print{body{background:white;color:black;margin:10mm}h1,h2{color:black}pre,th{background:#eee;color:black}}</style>");
        b.Append("<h1>Sarj QA Studio</h1><p>").Append(L("Evidence-based execution report", "تقرير تنفيذ مستند إلى الأدلة")).Append(" · ").Append(E(p.Name)).Append("</p><p>").Append(L("Target: ", "الهدف: ")).Append(E(p.Settings.BaseUrl)).Append("</p><p>").Append(L("Results apply only to the configured target. Local fixtures are demonstrations, not a production service.", "النتائج تخص الهدف المحدد فقط. النماذج المحلية للتجربة وليست خدمة إنتاجية.")).Append("</p>");
        var results = p.Runs.SelectMany(run => run.Results).ToList();
        b.Append("<h2>").Append(L("Execution summary", "ملخص التنفيذ")).Append("</h2><p>").Append(string.Join(" · ", results.GroupBy(r => r.Outcome).Select(g => $"{E(Outcome(g.Key))}: {g.Count()}"))).Append("</p><table><thead><tr>");
        foreach (var heading in new[] { L("Test", "الاختبار"), L("Outcome", "النتيجة"), L("Expected", "المتوقع"), L("Actual", "الفعلي"), L("Duration", "المدة") }) b.Append("<th scope='col'>").Append(heading).Append("</th>");
        b.Append("</tr></thead><tbody>");
        foreach (var run in p.Runs) foreach (var r in run.Results) {
            var test = run.TestCasesSnapshot.FirstOrDefault(t => t.Id == r.TestCaseId) ?? p.TestCases.FirstOrDefault(t => t.Id == r.TestCaseId);
            b.Append($"<tr><td>{E(test?.Title ?? r.TestCaseId)}</td><td class='{E(r.Outcome)}'>{E(Outcome(r.Outcome))}</td><td>{E(r.ExpectedResult)}</td><td>{E(r.ActualResult)}</td><td>{r.DurationMs:F2} ms</td></tr>");
        }
        b.Append("</tbody></table><h2>").Append(L("Detailed evidence and traceability", "الأدلة التفصيلية وتتبع المصدر")).Append("</h2>");
        foreach (var run in p.Runs) foreach (var r in run.Results) {
            var test = run.TestCasesSnapshot.FirstOrDefault(t => t.Id == r.TestCaseId) ?? p.TestCases.FirstOrDefault(t => t.Id == r.TestCaseId);
            var req = run.RequirementsSnapshot.FirstOrDefault(q => q.Id == test?.RequirementId) ?? p.Requirements.FirstOrDefault(q => q.Id == test?.RequirementId);
            b.Append($"<details open><summary>{E(test?.Title)} — {E(Outcome(r.Outcome))}</summary><p>{L("Run", "التشغيل")} {E(run.Id)} · {E(r.Timestamp.ToString("O"))} · {L("Evidence", "الدليل")} {E(r.EvidenceReference)}</p><p>{L("Source", "المصدر")} {E(req?.SourceId)} {E(req?.Reference)}: {E(req?.Text)}</p><pre>{E(JsonSerializer.Serialize(r, new JsonSerializerOptions(Store.Json) { WriteIndented = true }))}</pre></details>");
        }
        b.Append("<h2>").Append(L("Formal defect register", "سجل العيوب")).Append("</h2>");
        var number = 0;
        foreach (var run in p.Runs) foreach (var r in run.Results.Where(r => r.Outcome == "Failed" && r.AssertionOutcome != "Human observation; not an automated deterministic assertion")) {
            var test = run.TestCasesSnapshot.FirstOrDefault(t => t.Id == r.TestCaseId) ?? p.TestCases.FirstOrDefault(t => t.Id == r.TestCaseId);
            var triage = p.Defects.FirstOrDefault(d => d.EvidenceReference == r.EvidenceReference);
            b.Append($"<h3>SARJ-BUG-{++number:000}: {E(triage?.Title ?? test?.Title)}</h3><p>{L("Status", "الحالة")}: {E(triage?.Status ?? "Open")} · {L("Severity", "الشدة")}: {E(triage?.Severity ?? "Needs triage")} · {L("Priority", "الأولوية")}: {E(triage?.Priority ?? test?.Priority)}</p><p>{E(triage?.Description ?? L("Deterministic assertion mismatch.", "عدم تطابق في التحقق الآلي."))}</p><p>{L("Reproduction", "خطوات الإعادة")}: {E(string.Join("; ", triage?.ReproductionSteps ?? test?.Steps ?? []))}</p><p>{L("Expected", "المتوقع")}: {E(r.ExpectedResult)}. {L("Actual", "الفعلي")}: {E(r.ActualResult)}</p><pre>{E(r.AssertionOutcome)}</pre><p>{L("Evidence", "الدليل")}: {E(r.EvidenceReference)}</p>");
        }
        foreach (var d in p.Defects) b.Append($"<h3>{E(d.BugId)} — {L("Human triage", "مراجعة بشرية")}</h3><p>{E(d.Title)} · {E(d.Severity)} · {E(d.Priority)} · {E(d.Status)}</p><p>{E(d.Description)}</p><p>{E(string.Join("; ", d.ReproductionSteps))}</p>");
        b.Append("<h2>").Append(L("Limitations", "حدود النتائج")).Append("</h2><p>").Append(L("Network/authentication errors are environment blocks. Source references establish traceability, not completeness. Root cause and severity require investigation. Screenshots do not establish API behavior. Original source text and evidence remain unchanged in either language.", "أخطاء الشبكة والمصادقة تعني تعذر التنفيذ بسبب البيئة. مراجع المصدر تثبت التتبع لا الاكتمال. السبب الجذري والشدة يحتاجان تحقيقًا. الصور لا تثبت سلوك الواجهة البرمجية. نصوص المصادر والأدلة الأصلية لا تتغير بتغيير اللغة.")).Append("</p></html>");
        return b.ToString();
    }
